<?php require __DIR__.'/../_dashboard_start.php'; $class=$user['class_name'];
$s=$pdo->prepare('SELECT COUNT(*) FROM modules m JOIN classes c ON c.id=m.class_id WHERE c.name=? AND m.status="active"');$s->execute([$class]);$mods=(int)$s->fetchColumn();
$s=$pdo->prepare('SELECT COUNT(*) FROM tasks t JOIN modules m ON m.id=t.module_id JOIN classes c ON c.id=m.class_id LEFT JOIN submissions sub ON sub.task_id=t.id AND sub.student_id=? WHERE c.name=? AND sub.id IS NULL');$s->execute([$user['id'],$class]);$pending=(int)$s->fetchColumn();
$s=$pdo->prepare('SELECT COUNT(*),AVG(score) FROM submissions WHERE student_id=? AND score IS NOT NULL');$s->execute([$user['id']]);[$graded,$avg]=$s->fetch(PDO::FETCH_NUM);
$recent=$pdo->prepare('SELECT t.title,m.title module_title,t.deadline,sub.score,sub.feedback FROM tasks t JOIN modules m ON m.id=t.module_id JOIN classes c ON c.id=m.class_id LEFT JOIN submissions sub ON sub.task_id=t.id AND sub.student_id=? WHERE c.name=? ORDER BY t.created_at DESC LIMIT 6');$recent->execute([$user['id'],$class]);$tasks=$recent->fetchAll();
?>
<div class="page-heading"><div><span class="eyebrow">RUANG BELAJAR SISWA</span><h1>Halo, <?= e($user['name']) ?>!</h1><p><?= e($class ?: 'Kelas belum ditentukan') ?> · Semangat belajar dan raih prestasi terbaikmu.</p></div><a class="btn btn-primary" href="<?= e(url('learning')) ?>">Mulai Belajar <i class="fa-solid fa-arrow-right"></i></a></div>
<div class="stats-grid"><article class="stat-card"><div class="stat-icon purple"><i class="fa-solid fa-book-open"></i></div><div><span>Modul Aktif</span><strong><?= $mods ?></strong><small>Untuk kelas Anda</small></div></article><article class="stat-card"><div class="stat-icon orange"><i class="fa-solid fa-list-check"></i></div><div><span>Tugas Belum Selesai</span><strong><?= $pending ?></strong><small>Segera dikerjakan</small></div></article><article class="stat-card"><div class="stat-icon green"><i class="fa-solid fa-check-double"></i></div><div><span>Tugas Dinilai</span><strong><?= (int)$graded ?></strong><small>Sudah diperiksa guru</small></div></article><article class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-chart-line"></i></div><div><span>Rata-rata Nilai</span><strong><?= $avg!==null?number_format((float)$avg,1):'—' ?></strong><small>Dari tugas yang dinilai</small></div></article></div>
<section class="panel"><div class="panel-head"><h3>Tugas dan Hasil Terbaru</h3><a href="<?= e(url('tasks')) ?>">Lihat semua</a></div><?php if(!$tasks): ?><div class="empty-state">Belum ada tugas untuk kelas Anda.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Judul Tugas</th><th>Modul</th><th>Deadline</th><th>Nilai</th><th>Umpan Balik</th></tr></thead><tbody><?php foreach($tasks as $t): ?><tr><td><?= e($t['title']) ?></td><td><?= e($t['module_title']) ?></td><td><?= e(format_date($t['deadline'])) ?></td><td><?= $t['score']===null?'<span class="badge warning">Belum dinilai</span>':e($t['score']) ?></td><td><?= e($t['feedback']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/../_dashboard_end.php'; ?>